const form = $('Paste Your Leads').first().json;
const biz = $('Config: Your Business').first().json;
const settings = $('Config: Agent Settings').first().json;

const leads = String(form.Leads || '')
  .split('\n')
  .map((line) => line.trim())
  .filter(Boolean)
  .slice(0, Number(settings.max_leads_per_run) || 20)
  .map((line) => {
    const [company = '', website = '', person = ''] = line.split('|').map((s) => s.trim());
    let url = website;
    if (url && !/^https?:\/\//i.test(url)) url = 'https://' + url;
    return { json: {
      company,
      website: url,
      person,
      offer: form['What are you offering them?'] || biz.what_you_do,
    } };
  });

if (!leads.length) throw new Error('No leads found. Put one lead per line: Company | website | person');
return leads;

const decode = (s) => s
  .replace(/&nbsp;/g, ' ')
  .replace(/&quot;/g, '"')
  .replace(/&#39;|&#x27;|&apos;/g, "'")
  .replace(/&lt;/g, '<')
  .replace(/&gt;/g, '>')
  .replace(/&amp;/g, '&');
const lead = $('Clean Website Text').item.json;
const max = Number($('Config: Agent Settings').first().json.news_items_per_lead) || 3;
const xml = typeof $json.data === 'string' ? $json.data : '';
const pick = (block, tag) => {
  const m = block.match(new RegExp('<' + tag + '[^>]*>([\\s\\S]*?)<\\/' + tag + '>'));
  return m ? decode(m[1].replace(/<!\[CDATA\[|\]\]>/g, '').trim()) : '';
};
const news = (xml.match(/<item>[\s\S]*?<\/item>/g) || []).slice(0, max).map((block) => ({
  headline: pick(block, 'title'),
  link: pick(block, 'link'),
  date: pick(block, 'pubDate'),
  source: pick(block, 'source'),
}));
return { json: { ...lead, news } };

