function parseClaudeJson(text) {
  const raw = String(text || '').trim();
  const fenced = raw.match(/\x60\x60\x60(?:json)?\s*([\s\S]*?)\x60\x60\x60/);
  const candidate = fenced ? fenced[1] : raw.slice(raw.indexOf('{'), raw.lastIndexOf('}') + 1);
  try {
    return JSON.parse(candidate);
  } catch (e) {
    throw new Error('Claude did not return valid JSON. Raw reply: ' + raw.slice(0, 500));
  }
}
function esc(s) {
  return String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
}

const lead = $('Parse News').item.json;
let brief;
try {
  brief = parseClaudeJson($json.text);
} catch (e) {
  return { json: { company: lead.company, ok: false, html: '<h3>' + esc(lead.company) + '</h3><p>Could not write a brief: ' + esc(e.message) + '</p><hr>' } };
}

const newsHtml = (brief.recent_news || []).map((n) => {
  const match = lead.news.find((x) => x.headline === n.headline);
  const link = match ? ' <a href="' + esc(match.link) + '">source</a>' : '';
  return '<li>' + esc(n.headline) + link + '<br><i>' + esc(n.why_it_matters) + '</i></li>';
}).join('');

const html = '<h3>' + esc(lead.company) + (lead.person ? ' / ' + esc(lead.person) : '') + '</h3>' +
  (lead.website ? '<p><a href="' + esc(lead.website) + '">' + esc(lead.website) + '</a>' + (lead.site_found ? '' : ' (site could not be read)') + '</p>' : '') +
  '<p><b>What they do:</b> ' + esc(brief.what_they_do) + '</p>' +
  '<p><b>Recent news:</b></p>' + (newsHtml ? '<ul>' + newsHtml + '</ul>' : '<p><i>Nothing relevant found</i></p>') +
  '<p><b>Fit:</b> ' + esc(brief.fit) + '</p>' +
  '<p><b>Opener:</b> ' + esc(brief.opener) + '</p><hr>';

return { json: { company: lead.company, ok: true, html } };

const items = $input.all().map((i) => i.json);
const html = '<p>Research briefs for ' + items.length + ' lead' + (items.length === 1 ? '' : 's') +
  '. Check each opener against the source before you use it.</p><hr>' + items.map((i) => i.html).join('');
return [{ json: { subject: 'Lead research: ' + items.map((i) => i.company).slice(0, 3).join(', ') + (items.length > 3 ? ' + ' + (items.length - 3) + ' more' : ''), html } }];
